class Solution {
    public int halveArray(int[] nums) {
        double target = 0;
        double[] arr = new double[nums.length];
        for (int i = 0; i < nums.length; i++) { target += nums[i]; arr[i] = nums[i]; }
        target /= 2;
        int ans = 0;
        double reduced = 0;
        while (reduced < target) {
            int best = 0;
            for (int i = 1; i < arr.length; i++) if (arr[i] > arr[best]) best = i;
            reduced += arr[best] / 2;
            arr[best] /= 2;
            ans++;
        }
        return ans;
    }
};

