class Solution {
public:
    int halveArray(vector<int>& nums) {
        double target = accumulate(nums.begin(), nums.end(), 0.0) / 2;
        priority_queue<double> pq(nums.begin(), nums.end());
        int ans = 0;
        double reduced = 0;
        while (reduced < target) {
            double x = pq.top(); pq.pop();
            reduced += x / 2;
            pq.push(x / 2);
            ans++;
        }
        return ans;
    }
};

