class Solution {
    public int halveArray(int[] nums) {
        double target = 0;
        PriorityQueue<Double> pq = new PriorityQueue<>(Collections.reverseOrder());
        for (int x : nums) { target += x; pq.offer((double) x); }
        target /= 2;
        int ans = 0;
        double reduced = 0;
        while (reduced < target) {
            double x = pq.poll();
            reduced += x / 2;
            pq.offer(x / 2);
            ans++;
        }
        return ans;
    }
};

